import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const u=JSON.parse('{"title":"NACP","description":"","frontmatter":{},"headers":[],"relativePath":"transport/nacp.md","filePath":"transport/nacp.md","lastUpdated":1788343005000}'),r={name:"transport/nacp.md"};function c(s,t,i,l,n,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="nacp" tabindex="-1">NACP <a class="header-anchor" href="#nacp" aria-label="Permalink to &quot;NACP&quot;">​</a></h1><p>NACP 全称 Nyirusu Application Control <strong>Protocol</strong>。</p><p>NACP 是 NApp 通讯协议层，负责规范 NACPMessage 的 RPC-style 格式。</p><h2 id="nacp-message-type" tabindex="-1">NACP Message Type <a class="header-anchor" href="#nacp-message-type" aria-label="Permalink to &quot;NACP Message Type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>type</th><th>含义</th><th>ACK</th><th>期待回包</th></tr></thead><tbody><tr><td><code>register</code></td><td>注册，链接时发送的第一条消息</td><td>√</td><td><code>1 response</code></td></tr><tr><td><code>unregister</code></td><td>取消注册</td><td>√</td><td><code>1 response</code></td></tr><tr><td><code>request</code></td><td>请求，发送一次事件或能力调用</td><td>√</td><td><code>1 response</code> + <br><code>0~N notify</code></td></tr><tr><td><code>response</code></td><td>响应，表示一个消息的最终结果</td><td>√</td><td>-</td></tr><tr><td><code>subscribe</code></td><td>订阅，远程订阅一个NApp的消息总线</td><td>√</td><td><code>1 response</code></td></tr><tr><td><code>unsubscribe</code></td><td>取消订阅</td><td>√</td><td><code>1 response</code></td></tr><tr><td><code>notify</code></td><td>通知，发送订阅的中途消息</td><td>×</td><td>-</td></tr><tr><td><code>signal</code></td><td>信号，对一个正在进行中的事件发送中途补充</td><td>√</td><td>-</td></tr><tr><td><code>ack</code></td><td>知晓，表示对方已成功接收并准备处理消息</td><td>-</td><td>-</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>其中，<code>register</code>和<code>unregister</code>一般不需要NApp外部手动发送。</p><p>还需要注意的是，对于<code>notify</code>，接收方是不会发送<code>ack</code>消息确认的。</p></div><h2 id="更多" tabindex="-1">更多 <a class="header-anchor" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h2><ul><li>出站族函数与各消息类型详解：<a href="/transport/nacp/outbound">出站族函数</a></li><li>入站处理流程：<a href="/transport/nacp/inbound">入站族函数</a></li><li>上下线、宽限窗口与消息补发：<a href="/transport/nacp/lifecycle">生命周期</a></li><li>可观测：<a href="/transport/nacp/observability">可观测</a></li><li>Gateway 的使用方式：<a href="/napp/advanced/gateway">NApp Gateway</a></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ol><li>NACP被设计为可靠传输，具有一定消息队列性质，但以下缺陷是已知的、并且未来大概率不会去修正的：</li></ol><ul><li>断线重连、路由变动后一部分包发送可能会乱序，没有seq机制</li><li>没有进程意外退出后持久化保存队列</li><li><code>notify</code> 被设计为<code>MQTT Qos 0 Like</code>，即只发送、不确认对方是否收到。</li></ul><ol start="2"><li>NACP乃至NASDK <strong>都没有鉴权层</strong>、没有用户身份概念，默认连接的都是可信 App。</li><li>NACP的路由选择只看NACP消息中的<code>to</code>字段，Gateway也不会去转换和修改。</li></ol></div>',9)])])}const b=e(r,[["render",c]]);export{u as __pageData,b as default};
